import Foundation
import InventoryCore
import InventoryTestSupport
import Synchronization
import Testing
@testable import InventoryNetwork

/// Loads a JSON fixture from `Fixtures/` (generated by the scripts in `Fixtures/generator/`).
func loadFixture<T: Decodable>(_ name: String, as type: T.Type = T.self) throws -> T {
    let url = try #require(
        Bundle.module.url(forResource: name, withExtension: "json", subdirectory: "Fixtures"),
        "missing fixture \(name).json"
    )
    return try JSONDecoder().decode(T.self, from: Data(contentsOf: url))
}

/// Any JSON value, decodable from a fixture and encodable back unchanged
/// (used to send a recorded body, such as the import dump, through a client).
enum AnyJSON: Codable, Sendable, Equatable {
    case object([String: AnyJSON])
    case array([AnyJSON])
    case string(String)
    case number(Double)
    case bool(Bool)
    case null

    init(from decoder: any Decoder) throws {
        let container = try decoder.singleValueContainer()
        if container.decodeNil() { self = .null }
        else if let value = try? container.decode(Bool.self) { self = .bool(value) }
        else if let value = try? container.decode(Double.self) { self = .number(value) }
        else if let value = try? container.decode(String.self) { self = .string(value) }
        else if let value = try? container.decode([AnyJSON].self) { self = .array(value) }
        else { self = .object(try container.decode([String: AnyJSON].self)) }
    }

    func encode(to encoder: any Encoder) throws {
        var container = encoder.singleValueContainer()
        switch self {
        case .object(let value): try container.encode(value)
        case .array(let value): try container.encode(value)
        case .string(let value): try container.encode(value)
        case .number(let value):
            if value.rounded() == value, let integer = Int64(exactly: value) {
                try container.encode(integer)
            } else {
                try container.encode(value)
            }
        case .bool(let value): try container.encode(value)
        case .null: try container.encodeNil()
        }
    }

    var string: String? {
        if case .string(let value) = self { return value }
        return nil
    }

    var int64: Int64? {
        if case .number(let value) = self { return Int64(exactly: value) }
        return nil
    }
}

/// One recorded request and the real server's answer.
struct RecordedExchange: Decodable, Sendable {
    struct Request: Decodable, Sendable {
        let method: String
        let path: String
        let headers: [String: String]
        /// The JSON body text as the RN client builds it.
        let json: String?
        let base64: String?
    }

    struct Response: Decodable, Sendable {
        let status: Int
        let contentType: String?
        let cacheControl: String?
        let headers: [String: String]?
        let text: String?
        let base64: String?

        var body: Data {
            if let text { return Data(text.utf8) }
            if let base64, let data = Data(base64Encoded: base64) { return data }
            return Data()
        }

        var allHeaders: [String: String] {
            var merged = headers ?? [:]
            if let contentType { merged["content-type"] = contentType }
            if let cacheControl { merged["cache-control"] = cacheControl }
            return merged
        }

        var reply: StubReply {
            .response(status: status, headers: allHeaders, body: body, delay: nil)
        }
    }

    let request: Request
    let response: Response
}

/// Serves recorded answers for the requests that match them, in order: two
/// exchanges with the same method and path are answered one after the other.
func replay(_ exchanges: [RecordedExchange]) -> StubServer {
    let remaining = ExchangeQueue(exchanges)
    return StubServer { request in
        let match: RecordedExchange? = remaining.items.withLock { queue in
            guard let index = queue.firstIndex(where: { $0.request.method == request.method && $0.request.path == request.path }) else {
                return nil
            }
            return queue.remove(at: index)
        }
        guard let match else {
            return .json(599, #"{"error":"no recorded exchange for \#(request.method) \#(request.path)"}"#)
        }
        return match.response.reply
    }
}

private final class ExchangeQueue: Sendable {
    let items: Mutex<[RecordedExchange]>

    init(_ exchanges: [RecordedExchange]) {
        items = Mutex(exchanges)
    }
}

/// Checks that the client sent what the RN client sends for this exchange:
/// method, path, the recorded headers, and the same JSON (or bytes) body.
func expectRequest(
    _ sent: RecordedRequest?,
    matches exchange: RecordedExchange,
    sourceLocation: SourceLocation = #_sourceLocation
) {
    guard let sent else {
        Issue.record("no request was sent for \(exchange.request.method) \(exchange.request.path)", sourceLocation: sourceLocation)
        return
    }
    #expect(sent.method == exchange.request.method, sourceLocation: sourceLocation)
    #expect(sent.path == exchange.request.path, sourceLocation: sourceLocation)
    for (name, value) in exchange.request.headers {
        #expect(sent.header(name) == value, "header \(name)", sourceLocation: sourceLocation)
    }
    let recordedNames = Set(exchange.request.headers.keys.map { $0.lowercased() })
    if !recordedNames.contains("content-type") {
        #expect(sent.header("content-type") == nil, "unexpected Content-Type", sourceLocation: sourceLocation)
    }
    if let json = exchange.request.json {
        #expect(sent.json == JSONValue.parse(Data(json.utf8)), "JSON body", sourceLocation: sourceLocation)
    } else if let base64 = exchange.request.base64 {
        #expect(sent.body == Data(base64Encoded: base64), "byte body", sourceLocation: sourceLocation)
    } else {
        #expect(sent.body.isEmpty, "unexpected body", sourceLocation: sourceLocation)
    }
}

/// `household-contract.json`.
struct HouseholdContract: Decodable, Sendable {
    let origin: String
    let token: String
    let ids: [String: AnyJSON]
    let exchanges: [String: RecordedExchange]

    static func load() throws -> HouseholdContract { try loadFixture("household-contract") }

    func exchange(_ name: String) throws -> RecordedExchange {
        try #require(exchanges[name], "no exchange \(name)")
    }

    func id(_ name: String) throws -> String {
        try #require(ids[name]?.string, "no id \(name)")
    }

    func number(_ name: String) throws -> Int64 {
        try #require(ids[name]?.int64, "no number \(name)")
    }

    /// The response body parsed, for expectations derived from what the server said.
    func responseJSON(_ name: String) throws -> [String: AnyJSON] {
        let text = try #require(try exchange(name).response.text)
        guard case .object(let object) = try JSONDecoder().decode(AnyJSON.self, from: Data(text.utf8)) else {
            Issue.record("\(name) did not answer an object")
            return [:]
        }
        return object
    }
}

/// `sync-contract.json`.
struct SyncContract: Decodable, Sendable {
    let origin: String
    let code: String
    let appKey: String
    let photoId: String
    let exchanges: [String: RecordedExchange]

    static func load() throws -> SyncContract { try loadFixture("sync-contract") }

    func exchange(_ name: String) throws -> RecordedExchange {
        try #require(exchanges[name], "no exchange \(name)")
    }
}

/// `recognition-contract.json`.
struct RecognitionContract: Decodable, Sendable {
    struct Exchange: Decodable, Sendable {
        struct Request: Decodable, Sendable {
            let headers: [String: String]
            let json: String?
        }

        struct Response: Decodable, Sendable {
            let status: Int
            let contentType: String?
            let text: String
        }

        struct AdapterSaw: Decodable, Sendable {
            let mediaType: String
            let byteLength: Int
            let nameHint: String?
        }

        let request: Request
        let response: Response
        let adapterSaw: AdapterSaw?

        var reply: StubReply {
            .response(
                status: response.status,
                headers: ["Content-Type": response.contentType ?? "application/json"],
                body: Data(response.text.utf8),
                delay: nil
            )
        }
    }

    struct MediaType: Decodable, Sendable {
        let sent: String
        let accepted: String?
    }

    let endpoint: String
    let appKey: String
    /// The recorded image bytes, base64.
    let image: String
    let exchanges: [String: Exchange]
    let mediaTypes: [MediaType]

    static func load() throws -> RecognitionContract { try loadFixture("recognition-contract") }

    func exchange(_ name: String) throws -> Exchange {
        try #require(exchanges[name], "no exchange \(name)")
    }
}
